#include <string>
#include <sstream>
#include <vector>
using namespace std;

class Solution {
public:
    string reorderSpaces(string text) {
        int space = 0;
        for (char c : text)
            if (c == ' ') space++;

        stringstream ss(text);
        string word;
        vector<string> words;
        while (ss >> word) words.push_back(word);

        int gaps = words.size() - 1;
        string res;
        if (gaps == 0) {
            res = words[0] + string(space, ' ');
        } else {
            int even = space / gaps, rem = space % gaps;
            for (int i = 0; i < words.size(); ++i) {
                res += words[i];
                if (i < words.size() - 1)
                    res += string(even, ' ');
            }
            res += string(rem, ' ');
        }
        return res;
    }
};
